/**
 * The types `save/labs/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LabResearchSaveRow, LabQueueSaveRow, LabsSaveExtract
 * depends    —
 * used by    src/save/labs/index, src/save/labs/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from read.ts

export interface LabResearchSaveRow {
  index: number
  level: number
  displayName: string | null
  slug: string | null
  category: string | null
  gameField: string | null
  percentComplete: number | null
  remainingSeconds: number | null
}

export interface LabQueueSaveRow {
  slotIndex: number
  labLevel: number | null
  researchInt: number | null
  active: boolean
  speedUp: number | null
  speedUpRemainingSeconds: number | null
  research: LabResearchSaveRow | null
}

export interface LabsSaveExtract {
  labsUnlocked: number | null
  researchesComplete: number | null
  totalCoinsSpentOnResearch: unknown
  /** Unknown entries retain their slot as null; warnings identify unreadable fields. */
  speedUpSpeed: (number | null)[]
  speedUpRemainingSeconds: (number | null)[]
  activeQueue: LabQueueSaveRow[]
  /** False when the export omits queue fields; consumers should preserve their existing queue. */
  hasActiveQueueData?: boolean
  researches: LabResearchSaveRow[]
  researchedCount: number
  maxedCount: number
  namedResearchCount: number
  hiddenUnnamedCount: number
  /** Slugs the player starred in game, from the save's `favoriteLabs` indices. */
  favoriteLabs: string[]
  /** False when the save predates the field, so favourites must not be overwritten. */
  hasFavoriteLabs: boolean
  warnings: string[]
}
